def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    out: list[str] = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        escaped = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if run_len >= 3:
            out.append(str(run_len))
            out.append(escaped)
        elif run_len == 2:
            out.append(escaped)
            out.append(escaped)
        else:
            out.append(escaped)
        i = j
    return "".join(out)
